export interface ConnectorConfig {
  /** Full Discord incoming webhook URL including webhook ID and token. */
  discordWebhookUrl: string
  /** Optional fetch implementation for testing or customization. */
  fetch?: typeof fetch
}

export interface AirtableWebhookPayload {
  id: string
  fields: Record<string, unknown>
  createdTime: string
}

export interface DiscordWebhookPayload {
  content?: string
  embeds?: DiscordEmbed[]
  timestamp?: string
}

export interface DiscordEmbed {
  title?: string
  description?: string
  fields?: DiscordEmbedField[]
  timestamp?: string
}

export interface DiscordEmbedField {
  name: string
  value: string
  inline?: boolean
}

export interface HandleResult {
  /** Discord message ID if returned (when wait=true), otherwise undefined. */
  messageId?: string
  /** The webhook URL that was called. */
  webhookUrl: string
}

function validatePayload(payload: unknown): asserts payload is AirtableWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'string' || p.id.length === 0) {
    throw new Error('Missing required field: id (string)')
  }
  if (!p.fields || typeof p.fields !== 'object' || Array.isArray(p.fields)) {
    throw new Error('Missing required field: fields (object)')
  }
  if (typeof p.createdTime !== 'string' || p.createdTime.length === 0) {
    throw new Error('Missing required field: createdTime (ISO 8601 string)')
  }
}

function mapFieldsToEmbed(fields: Record<string, unknown>): DiscordEmbed {
  const embedFields: DiscordEmbedField[] = Object.entries(fields).map(([name, value]) => ({
    name,
    value: String(value),
    inline: true
  }))
  return {
    fields: embedFields,
    timestamp: new Date().toISOString()
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const airtablePayload = payload as AirtableWebhookPayload

  const embed = mapFieldsToEmbed(airtablePayload.fields)

  const discordPayload: DiscordWebhookPayload = {
    content: airtablePayload.id,
    embeds: [embed],
    timestamp: airtablePayload.createdTime
  }

  const url = config.discordWebhookUrl + (config.discordWebhookUrl.includes('?') ? '&' : '?') + 'wait=true'
  const fetchImpl = config.fetch ?? fetch

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(discordPayload)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Discord webhook request failed: ${response.status} ${response.statusText} at ${url}. Response: ${text}`
    )
  }

  let messageId: string | undefined
  if (response.status !== 204) {
    const data = await response.json().catch(() => ({})) as { id?: string }
    messageId = data.id
  }

  return {
    messageId,
    webhookUrl: config.discordWebhookUrl
  }
}

