    baseConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch: mockFetch
    }
  })

  it('sends correct payload with mapped fields on happy path', async () => {
    const payload: AirtableWebhookPayload = {
      id: 'recABCDEFGHIJKL',
      fields: {
        Name: 'Jane Smith',
        Email: 'jane@example.com',
        Status: 'Active'
      },
      createdTime: '2023-05-15T08:30:00.000Z'
    }

    const result = await handle(payload, baseConfig)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toContain('wait=true')
    expect(call.json).toEqual(
      expect.objectContaining({
        content: 'recABCDEFGHIJKL',
        timestamp: '2023-05-15T08:30:00.000Z',
        embeds: expect.arrayContaining([
          expect.objectContaining({
            fields: expect.arrayContaining([
              expect.objectContaining({ name: 'Name', value: 'Jane Smith', inline: true }),
              expect.objectContaining({ name: 'Email', value: 'jane@example.com', inline: true }),
              expect.objectContaining({ name: 'Status', value: 'Active', inline: true })
            ])
          })
        ])
      })
    )
    expect(result.messageId).toBe('msg_123')
  })

  it('uses injected fetch and includes auth via URL token', async () => {
    const payload: AirtableWebhookPayload = {
      id: 'recTEST123',
      fields: { Foo: 'Bar' },
      createdTime: '2023-01-01T00:00:00.000Z'
    }

    await handle(payload, baseConfig)

    const call = calls[0]
    expect(call.url).toBe('https://discord.com/api/webhooks/123456/abcdef?wait=true')
    expect(call.headers.get('authorization')).toBeNull()
    expect(call.headers.get('content-type')).toBe('application/json')
  })

  it('throws descriptive error when id is missing', async () => {
    const payload = {
      fields: { Name: 'Test' },
      createdTime: '2023-01-01T00:00:00.000Z'
    }

    await expect(handle(payload as unknown as AirtableWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: id'
    )
    expect(calls.length).toBe(0)
  })

  it('throws descriptive error when fields is missing', async () => {
    const payload = {
      id: 'rec123',
      createdTime: '2023-01-01T00:00:00.000Z'
    }

    await expect(handle(payload as unknown as AirtableWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: fields'
    )
    expect(calls.length).toBe(0)
  })

  it('throws descriptive error when createdTime is missing', async () => {
    const payload = {
      id: 'rec123',
      fields: { Name: 'Test' }
    }

    await expect(handle(payload as unknown as AirtableWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: createdTime'
    )
    expect(calls.length).toBe(0)
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch
    }
    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: { Name: 'Test' },
      createdTime: '2023-01-01T00:00:00.000Z'
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Discord webhook request failed: 401 Unauthorized at https://discord.com/api/webhooks/123456/abcdef?wait=true'
    )
    expect(errorCalls.length).toBe(1)
  })

  it('handles 204 No Content response without message ID', async () => {
    const { fetch, calls: noContentCalls } = fakeFetch(() => jsonResponse(null, 204))
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch
    }
    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: { Name: 'Test' },
      createdTime: '2023-01-01T00:00:00.000Z'
    }

    const result = await handle(payload, config)
    expect(result.messageId).toBeUndefined()
    expect(noContentCalls.length).toBe(1)
  })

  it('maps empty fields object to embed with empty fields array', async () => {
    const payload: AirtableWebhookPayload = {
      id: 'recEMPTY',
      fields: {},
      createdTime: '2023-01-01T00:00:00.000Z'
    }

